// Hand-authored: shared helpers for the financial reconciliation commands
// (recognized-revenue, invoiced, reconcile). Not generated — do not add the
// "Generated by CLI Printing Press" header or regen will treat it as templated.

package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"strconv"
	"time"

	"github.com/mvanhorn/printing-press-library/library/productivity/productive/internal/client"
)

// financialItemReportPath is the JSON:API report endpoint. Reports live under
// /reports/<report_type> (verified: bare /financial_item_reports is 404).
const financialItemReportPath = "/reports/financial_item_reports"

// reportPageThrottle keeps multi-page report pulls under Productive's tight
// report rate limit (10 requests / 30 s ≈ 1 per 3 s).
const reportPageThrottle = 3 * time.Second

// japiResource is one JSON:API resource object (report row, budget, etc.).
type japiResource struct {
	ID            string                     `json:"id"`
	Type          string                     `json:"type"`
	Attributes    map[string]json.RawMessage `json:"attributes"`
	Relationships map[string]json.RawMessage `json:"relationships"`
}

// japiDoc is a JSON:API top-level document (list response).
type japiDoc struct {
	Data     []japiResource             `json:"data"`
	Included []japiResource             `json:"included"`
	Meta     map[string]json.RawMessage `json:"meta"`
}

// relID extracts the related resource id from a to-one relationship blob
// (`{"data":{"id":"5","type":"deals"}}`); returns "" for null/absent/to-many.
func relID(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	var wrap struct {
		Data struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.Unmarshal(raw, &wrap); err != nil {
		return ""
	}
	return wrap.Data.ID
}

// metaInt reads an integer field from the response meta (total_pages etc.).
func metaInt(meta map[string]json.RawMessage, key string) (int, bool) {
	raw, ok := meta[key]
	if !ok {
		return 0, false
	}
	var n json.Number
	if err := json.Unmarshal(raw, &n); err != nil {
		return 0, false
	}
	i, err := n.Int64()
	if err != nil {
		return 0, false
	}
	return int(i), true
}

// fetchFinancialItemReport pulls every page of a financial_item_report query,
// returning all rows plus an id->resource map of sideloaded `included` records
// (used to resolve budget names). params must already contain group/filter keys;
// pagination keys are managed here.
func fetchFinancialItemReport(ctx context.Context, c *client.Client, params map[string]string) ([]japiResource, map[string]japiResource, error) {
	if params == nil {
		params = map[string]string{}
	}
	if params["page[size]"] == "" {
		params["page[size]"] = "200"
	}
	pageSize, _ := strconv.Atoi(params["page[size]"])

	var rows []japiResource
	included := map[string]japiResource{}
	page := 1
	for {
		params["page[number]"] = strconv.Itoa(page)
		body, err := c.Get(ctx, financialItemReportPath, params)
		if err != nil {
			return nil, nil, err
		}
		var doc japiDoc
		if err := json.Unmarshal(body, &doc); err != nil {
			return nil, nil, fmt.Errorf("parsing financial_item_reports response: %w", err)
		}
		rows = append(rows, doc.Data...)
		for _, inc := range doc.Included {
			included[inc.Type+":"+inc.ID] = inc
		}
		total, ok := metaInt(doc.Meta, "total_pages")
		if ok {
			if page >= total {
				break
			}
		} else if pageSize <= 0 || len(doc.Data) < pageSize {
			// No total_pages in meta: fall back to the full-page heuristic —
			// a short (or empty) page means the end of the result set. Without
			// this the loop would stop after page 1 whenever the API omits
			// total_pages, understating recognized/invoiced/reconciled totals.
			break
		}
		page++
		time.Sleep(reportPageThrottle)
	}
	return rows, included, nil
}

// budgetName resolves a budget/deal display name from the included map.
func budgetName(included map[string]japiResource, budgetID string) string {
	if budgetID == "" {
		return ""
	}
	for _, key := range []string{"deals:" + budgetID, "budgets:" + budgetID} {
		if res, ok := included[key]; ok {
			if raw, ok := res.Attributes["name"]; ok {
				var s string
				if json.Unmarshal(raw, &s) == nil {
					return s
				}
			}
		}
	}
	return ""
}

// rowString returns the first present attribute among keys as a string.
func rowString(attrs map[string]json.RawMessage, keys ...string) string {
	for _, k := range keys {
		if raw, ok := attrs[k]; ok && len(raw) > 0 {
			var s string
			if json.Unmarshal(raw, &s) == nil && s != "" {
				return s
			}
			// Non-string scalar (number/bool) — return raw trimmed of quotes.
			return string(raw)
		}
	}
	return ""
}

// rowMoneyCents returns an integer cents metric from a report row attribute.
func rowMoneyCents(attrs map[string]json.RawMessage, key string) int64 {
	raw, ok := attrs[key]
	if !ok || len(raw) == 0 {
		return 0
	}
	var n json.Number
	if err := json.Unmarshal(raw, &n); err != nil {
		return 0
	}
	i, err := n.Int64()
	if err != nil {
		// Some money fields may arrive as float strings; fall back.
		f, ferr := n.Float64()
		if ferr != nil {
			return 0
		}
		return int64(f)
	}
	return i
}

// flattenReportRow merges a report row's attributes with its resolved budget id
// and name so JSON/CSV/table output is a flat, agent-friendly record.
func flattenReportRow(row japiResource, included map[string]japiResource) map[string]any {
	out := map[string]any{}
	for k, raw := range row.Attributes {
		var v any
		if json.Unmarshal(raw, &v) == nil {
			out[k] = v
		}
	}
	if bid := relID(row.Relationships["budget"]); bid != "" {
		out["budget_id"] = bid
		if name := budgetName(included, bid); name != "" {
			out["budget_name"] = name
		}
	}
	out["id"] = row.ID
	return out
}

// applyReportGroupAndDates builds the shared param set for a budget×period
// financial report query.
func applyReportGroupAndDates(params map[string]string, groupEntity, bucket, from, to string) {
	group := groupEntity
	if bucket != "" {
		group = groupEntity + ",date:" + bucket
	}
	params["group"] = group
	if from != "" {
		params["filter[date][gt_eq]"] = from
	}
	if to != "" {
		params["filter[date][lt_eq]"] = to
	}
	// Sideload budgets so we can show names alongside ids.
	params["include"] = "budget"
}
